CREATE TABLE `ourlink_db1`.`bib_books` ( `book_id` INT NOT NULL , `name_en` VARCHAR(100) NOT NULL , `name_es` VARCHAR(100) NULL DEFAULT NULL , `name_de` VARCHAR(100) NULL DEFAULT NULL , `name_pt` VARCHAR(100) NULL DEFAULT NULL , `name_fr` VARCHAR(100) NULL DEFAULT NULL , `order_jerusalem_en` INT NOT NULL DEFAULT '100' , `order_jerusalem_es` INT NOT NULL DEFAULT '100' , `is_new_testament` BIT(1) NULL DEFAULT NULL , `genre_id` TINYINT NULL DEFAULT NULL , `is_canonical` BIT(1) NOT NULL DEFAULT b'0' , `chapter_count` SMALLINT NULL DEFAULT NULL , `old_book_id` VARCHAR(3) NULL DEFAULT NULL , `testament` VARCHAR(2) NULL DEFAULT NULL , `alt_id_1` INT NULL DEFAULT NULL ) ENGINE = InnoDB CHARSET=utf8 COLLATE utf8_general_ci;



ALTER TABLE `bib_verses` CHANGE `book_id` `book_old_id` CHAR(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL;

ALTER TABLE `bib_verses` ADD `verse_id` INT(8) UNSIGNED ZEROFILL NULL DEFAULT NULL AFTER `translation_id`, ADD `book_id` INT NULL DEFAULT NULL AFTER `verse_id`;
